Here is the commit message:
net: qede: fix PTP initialization on recovery

Currently PTP cyclecounter and timecounter are initialized only on
the first probing and are cleaned up during removal. This means that
PTP becomes non-functional after device recovery.
Fix this by unconditional PTP initialization on probing and clearing
Tx pending bit on exiting.

Fixes: ccc67ef50b90 ("qede: Error recovery process")
Signed-off-by: Alexander Lobakin <alobakin@marvell.com>
Signed-off-by: Igor Russkikh <irusskikh@marvell.com>
Signed-off-by: Michal Kalderon <michal.kalderon@marvell.com>
Signed-off-by: David S. Miller <davem@davemloft.net>

Here is the root cause:
The bug was caused by the PTP cyclecounter and timecounter being initialized only during the first probing of the device. This meant that after a device recovery, the PTP functionality was not re-initialized, leading to non-functional PTP operations. The lack of unconditional initialization on subsequent probes resulted in the failure of PTP applications when the device was unloaded and reloaded while still in use.

Here is the patch:

 static int __qede_probe(struct pci_dev *pdev, u32 dp_module, u8 dp_level,
 			bool is_vf, enum qede_probe_mode mode)
 {
 	struct qed_probe_params probe_params;
 	struct qed_slowpath_params sp_params;
 	struct qed_dev_eth_info dev_info;
 	struct qede_dev *edev;
 	struct qed_dev *cdev;
 	int rc;

 	if (unlikely(dp_level & QED_LEVEL_INFO))
 		pr_notice("Starting qede probe\n");

 	memset(&probe_params, 0, sizeof(probe_params));
 	probe_params.protocol = QED_PROTOCOL_ETH;
 	probe_params.dp_module = dp_module;
 	probe_params.dp_level = dp_level;
 	probe_params.is_vf = is_vf;
 	probe_params.recov_in_prog = (mode == QEDE_PROBE_RECOVERY);
 	cdev = qed_ops->common->probe(pdev, &probe_params);
 	if (!cdev) {
 		rc = -ENODEV;
 		goto err0;
 	}

 	qede_update_pf_params(cdev);

 	/* Start the Slowpath-process */
 	memset(&sp_params, 0, sizeof(sp_params));
 	sp_params.int_mode = QED_INT_MODE_MSIX;
 	sp_params.drv_major = QEDE_MAJOR_VERSION;
 	sp_params.drv_minor = QEDE_MINOR_VERSION;
 	sp_params.drv_rev = QEDE_REVISION_VERSION;
 	sp_params.drv_eng = QEDE_ENGINEERING_VERSION;
 	strlcpy(sp_params.name, "qede LAN", QED_DRV_VER_STR_SIZE);
 	rc = qed_ops->common->slowpath_start(cdev, &sp_params);
 	if (rc) {
 		pr_notice("Cannot start slowpath\n");
 		goto err1;
 	}

 	/* Learn information crucial for qede to progress */
 	rc = qed_ops->fill_dev_info(cdev, &dev_info);
 	if (rc)
 		goto err2;

 	if (mode != QEDE_PROBE_RECOVERY) {
 		edev = qede_alloc_etherdev(cdev, pdev, &dev_info, dp_module,
 					   dp_level);
 		if (!edev) {
 			rc = -ENOMEM;
 			goto err2;
 		}
 	} else {
 		struct net_device *ndev = pci_get_drvdata(pdev);

 		edev = netdev_priv(ndev);
 		edev->cdev = cdev;
 		memset(&edev->stats, 0, sizeof(edev->stats));
 		memcpy(&edev->dev_info, &dev_info, sizeof(dev_info));
 	}

 	if (is_vf)
 		set_bit(QEDE_FLAGS_IS_VF, &edev->flags);

 	qede_init_ndev(edev);

 	rc = qede_rdma_dev_add(edev, (mode == QEDE_PROBE_RECOVERY));
 	if (rc)
 		goto err3;

 	if (mode != QEDE_PROBE_RECOVERY) {
 		/* Prepare the lock prior to the registration of the netdev,
 		 * as once it's registered we might reach flows requiring it
 		 * [it's even possible to reach a flow needing it directly
 		 * from there, although it's unlikely].
 		 */
 		INIT_DELAYED_WORK(&edev->sp_task, qede_sp_task);
 		mutex_init(&edev->qede_lock);

 		rc = register_netdev(edev->ndev);
 		if (rc) {
 			DP_NOTICE(edev, "Cannot register net-device\n");
 			goto err4;
 		}
 	}

 	edev->ops->common->set_name(cdev, edev->ndev->name);

 	/* PTP not supported on VFs */
 	if (!is_vf)
-		qede_ptp_enable(edev, (mode == QEDE_PROBE_NORMAL));
+		qede_ptp_enable(edev);

 	edev->ops->register_ops(cdev, &qede_ll_ops, edev);

 #ifdef CONFIG_DCB
 	if (!IS_VF(edev))
 		qede_set_dcbnl_ops(edev->ndev);
 #endif

 	edev->rx_copybreak = QEDE_RX_HDR_SIZE;

 	qede_log_probe(edev);
 	return 0;

 err4:
 	qede_rdma_dev_remove(edev, (mode == QEDE_PROBE_RECOVERY));
 err3:
 	free_netdev(edev->ndev);
 err2:
 	qed_ops->common->slowpath_stop(cdev);
 err1:
 	qed_ops->common->remove(cdev);
 err0:
 	return rc;
 }



